package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	line = strings.TrimSpace(line)
	parts := strings.Split(line, " ")
	n, _ := strconv.Atoi(parts[0])
	t, _ := strconv.Atoi(parts[1])

	// dp[i][prev_y][curr_y][humps][valleys] = count
	// i is the current length of the sequence (number of vertices placed so far)
	// We use two layers to save memory, but given constraints (n=20, y=4) full array is small.
	// Max humps t <= 10, valleys t-1 <= 9.
	// Dimensions: n+1, 5, 5, t+1, t+1 (valleys up to t)
	dp := make([][][][][]int64, n+1)
	for i := range dp {
		dp[i] = make([][][][]int64, 5)
		for py := range dp[i] {
			dp[i][py] = make([][][]int64, 5)
			for cy := range dp[i][py] {
				dp[i][py][cy] = make([][]int64, t+1)
				for h := range dp[i][py][cy] {
					dp[i][py][cy][h] = make([]int64, t+1) // valleys index up to t
				}
			}
		}
	}

	// Initialize for length 2 (first two vertices x=1, x=2)
	// y1, y2 in 1..4, y1 != y2
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 != y2 {
				dp[2][y1][y2][0][0] = 1
			}
		}
	}

	// Iterate length from 3 to n
	for len := 3; len <= n; len++ {
		for py := 1; py <= 4; py++ {       // y_{len-2}
			for cy := 1; cy <= 4; cy++ {   // y_{len-1}
				if py == cy {
					continue // no horizontal segments
				}
				for h := 0; h <= t; h++ {
					for v := 0; v <= t; v++ {
						count := dp[len-1][py][cy][h][v]
						if count == 0 {
							continue
						}
						// Try next y (y_len)
						for ny := 1; ny <= 4; ny++ {
							if cy == ny {
								continue // no horizontal segments
							}
							nh := h
							nv := v
							// Check vertex at index len-1 (which is cy)
							// Condition: py < cy > ny -> hump
							// Condition: py > cy < ny -> valley
							if py < cy && cy > ny {
								nh++
							} else if py > cy && cy < ny {
								nv++
							}
							if nh <= t && nv <= t {
								dp[len][cy][ny][nh][nv] += count
							}
						}
					}
				}
			}
		}
	}

	// Sum up results for length n with exactly t humps and t-1 valleys
	var ans int64
	for py := 1; py <= 4; py++ {
		for cy := 1; cy <= 4; cy++ {
			if py != cy {
				if t-1 >= 0 && t-1 <= t {
					ans += dp[n][py][cy][t][t-1]
				}
			}
		}
	}

	fmt.Println(ans)
}
